<section class="mx-auto max-w-5xl px-4 py-12 sm:px-6 lg:px-8"><h1 class="text-4xl font-semibold">Your cart</h1>@if ($cart->lines->isEmpty())<div class="mt-10 rounded-2xl bg-zinc-100 p-10 text-center dark:bg-zinc-900"><p>Your cart is empty</p><flux:button class="mt-4" :href="route('storefront.collections.index')">Continue shopping</flux:button></div>@else<div class="mt-10 grid gap-8 lg:grid-cols-[1fr_20rem]"><div class="grid gap-4">@foreach ($cart->lines as $line)<article wire:key="cart-line-{{ $line->id }}" class="flex gap-4 rounded-2xl border border-zinc-200 p-4 dark:border-zinc-800"><div class="size-24 rounded-xl bg-zinc-100 dark:bg-zinc-800"></div><div class="min-w-0 flex-1"><h2 class="font-medium">{{ $line->variant->product->title }}</h2><x-storefront.price :amount="$line->line_total_amount" :currency="$cart->currency" /><div class="mt-3 flex flex-wrap items-center gap-2"><flux:button size="sm" wire:click="updateQuantity({{ $line->id }}, {{ max(0, $line->quantity - 1) }})" aria-label="Decrease quantity">−</flux:button><span aria-live="polite">{{ $line->quantity }}</span><flux:button size="sm" wire:click="updateQuantity({{ $line->id }}, {{ $line->quantity + 1 }})" aria-label="Increase quantity">+</flux:button><flux:button size="sm" variant="ghost" wire:click="removeLine({{ $line->id }})">Remove</flux:button></div></div></article>@endforeach</div><aside class="h-fit rounded-2xl bg-zinc-100 p-6 dark:bg-zinc-900"><h2 class="text-xl font-semibold">Order summary</h2><div class="mt-5 flex justify-between"><span>Subtotal</span><x-storefront.price :amount="$cart->lines->sum('line_total_amount')" :currency="$cart->currency" /></div><flux:button wire:click="checkout" variant="primary" class="mt-6 w-full">Checkout</flux:button></aside></div>@endif</section>
